create sequence if not exists public.trackfit_invoice_number_seq;
create table if not exists public.trackfit_invoice_settings(id boolean primary key default true check(id),business_name text not null default 'Apex Curtains Ltd',trading_name text not null default 'TrackFit',business_address jsonb not null default '{}'::jsonb,telephone text not null default '',email text not null default '',website text not null default '',company_number text not null default '',bank_details jsonb not null default '{"account_name":"Apex Curtains Ltd"}'::jsonb,payment_instructions text not null default '',invoice_footer text not null default 'Thank you for choosing TrackFit.',logo_path text not null default '/logos/trackfit-logo.svg',updated_at timestamptz not null default now(),updated_by uuid references auth.users);
create table if not exists public.trackfit_invoices(id uuid primary key default gen_random_uuid(),invoice_number text unique,status text not null default 'draft' check(status in('draft','issued','part_paid','paid','overdue','cancelled','credited')),invoice_type text not null default 'full' check(invoice_type in('full','deposit','balance','part_payment','paid','credit_note')),revision integer not null default 1,replaces_invoice_id uuid references public.trackfit_invoices,lead_id uuid references public.trackfit_enquiries on delete set null,customer_details jsonb not null,billing_address jsonb not null default '{}'::jsonb,installation_address jsonb not null default '{}'::jsonb,invoice_date date not null,due_date date not null,purchase_order text,customer_reference text,job_description text,currency text not null default 'GBP',subtotal_pence bigint not null,discount_pence bigint not null,vat_pence bigint not null,total_pence bigint not null,amount_paid_pence bigint not null default 0,balance_due_pence bigint not null,customer_notes text,internal_notes text,payment_terms text,payment_details jsonb not null default '{}'::jsonb,pdf_path text,issued_at timestamptz,paid_at timestamptz,cancelled_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),created_by uuid not null references auth.users,check(due_date>=invoice_date),check(total_pence>=0));
create table if not exists public.trackfit_invoice_items(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.trackfit_invoices on delete cascade,position integer not null,description text not null,quantity_milli integer not null check(quantity_milli>0),unit text not null,unit_price_pence bigint not null check(unit_price_pence>=0),discount_type text not null check(discount_type in('none','percentage','fixed')),discount_value integer not null default 0,vat_rate_bps integer not null default 0,line_subtotal_pence bigint not null);
create table if not exists public.trackfit_invoice_activity(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.trackfit_invoices on delete cascade,actor_id uuid references auth.users,activity_type text not null,description text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.next_trackfit_invoice_number() returns text language plpgsql security definer set search_path='' as $$ declare n bigint; begin if not public.is_trackfit_admin() then raise exception 'unauthorised'; end if; n:=nextval('public.trackfit_invoice_number_seq'); return 'TF-INV-'||extract(year from current_date)::int||'-'||lpad(n::text,6,'0'); end $$;
create index if not exists trackfit_invoices_due_idx on public.trackfit_invoices(due_date); create index if not exists trackfit_invoices_created_idx on public.trackfit_invoices(created_at desc); create index if not exists trackfit_invoice_items_invoice_idx on public.trackfit_invoice_items(invoice_id,position); create index if not exists trackfit_invoice_activity_invoice_idx on public.trackfit_invoice_activity(invoice_id,created_at desc);
alter table public.trackfit_invoices enable row level security;alter table public.trackfit_invoice_items enable row level security;alter table public.trackfit_invoice_activity enable row level security;alter table public.trackfit_invoice_settings enable row level security;
grant select,insert,update,delete on public.trackfit_invoices,public.trackfit_invoice_items to authenticated;grant select,insert on public.trackfit_invoice_activity to authenticated;grant select,insert,update on public.trackfit_invoice_settings to authenticated;grant usage on sequence public.trackfit_invoice_number_seq to authenticated;grant execute on function public.next_trackfit_invoice_number() to authenticated;
create policy "admins invoices" on public.trackfit_invoices for all to authenticated using(public.is_trackfit_admin()) with check(public.is_trackfit_admin() and created_by=auth.uid());create policy "admins items" on public.trackfit_invoice_items for all to authenticated using(public.is_trackfit_admin()) with check(public.is_trackfit_admin());create policy "admins activity" on public.trackfit_invoice_activity for select to authenticated using(public.is_trackfit_admin());create policy "admins add activity" on public.trackfit_invoice_activity for insert to authenticated with check(public.is_trackfit_admin() and actor_id=auth.uid());create policy "admins settings" on public.trackfit_invoice_settings for all to authenticated using(public.is_trackfit_admin()) with check(public.is_trackfit_admin());
insert into public.trackfit_invoice_settings(id) values(true) on conflict do nothing;
